function formatResetRemaining(e){if(!e)return null;const t=e-Date.now();if(t<=0)return`now`;const n=Math.floor(t/6e4);if(n<60)return`${n}m`;const r=Math.floor(n/60);const i=n%60;if(r<24)return i>0?`${r}h ${i}m`:`${r}h`;const a=Math.floor(r/24);if(a<7)return`${a}d ${r%24}h`;return new Intl.DateTimeFormat(`en-US`,{month:`short`,day:`numeric`}).format(new Date(e))}function formatBillingAmount(e,t){const n=t.trim().toUpperCase();if(n===`USD`)return e<0?`-$${Math.abs(e).toFixed(2)}`:`$${e.toFixed(2)}`;if(n===`CNY`||n===`RMB`)return e<0?`-¥${Math.abs(e).toFixed(2)}`:`¥${e.toFixed(2)}`;return`${e.toFixed(2)} ${t}`}function formatBillingEntry(e){const t=e.label??(e.type===`balance`?`Balance`:e.type===`spend`?`Usage`:`Budget`);if(e.type===`budget`)return`${t}: ${formatBillingAmount(e.used,e.unit)} / ${formatBillingAmount(e.limit,e.unit)}`;return`${t}: ${formatBillingAmount(e.amount,e.unit)}`}function formatUsageWindowSummary(e){if(e.error)return null;if(e.windows.length===0){const t=e.billing?.[0];return e.summary?.trim()||(t?formatBillingEntry(t):null)}return e.windows.slice(0,2).map(e=>{const t=clampPercent(100-e.usedPercent);const n=formatResetRemaining(e.resetAt);const r=n?` ⏱${n}`:``;return`${e.label} ${t.toFixed(0)}% left${r}`}).join(` · `)}function formatUsageReportLines(e){if(e.providers.length===0)return[`Usage: no provider usage available.`];const t=[`Usage:`];for(const n of e.providers){const e=n.plan?` (${n.plan})`:``;if(n.error){t.push(`  ${n.displayName}${e}: ${n.error}`);continue}if(n.windows.length===0&&!n.billing?.length){t.push(`  ${n.displayName}${e}: ${n.summary?.trim()||`no data`}`);continue}t.push(`  ${n.displayName}${e}`);if(n.summary?.trim())t.push(`    ${n.summary.trim()}`);for(const e of n.windows){const n=clampPercent(100-e.usedPercent);const r=formatResetRemaining(e.resetAt);const i=r?` · resets ${r}`:``;t.push(`    ${e.label}: ${n.toFixed(0)}% left${i}`)}for(const e of n.billing??[])t.push(`    ${formatBillingEntry(e)}`)}return t}export{formatUsageWindowSummary as n,formatUsageReportLines as t};